css:
.print-format {
    padding: 15px !important;
}

body {
    font-family: Arial, sans-serif;
    font-size: 13px;
    color: #000;
    margin: 0;
}

body * {
    font-family: Arial, sans-serif;
    font-size: 13px;
    line-height: 1.5em;
    box-sizing: border-box;
}

.title {
    font-size: 20px;
    font-weight: bold;
    text-align: center;
    padding-bottom: 4px;
}

.section-label {
    font-weight: bold;
    font-size: 20px;
}

table.outer {
    width: 100%;
    border: none;
    margin-bottom: 10px;
}

table.outer td {
    vertical-align: top;
    padding: 4px;
}

table.data-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
}

table.data-table th,
table.data-table td {
    border: 1px solid #000;
    padding: 6px;
    text-align: center;
}

table.data-table th {
    background-color: #f5f5f5;
    font-weight: bold;
}

.text-left {
    text-align: left !important;
}

.child-arrow {
    padding-left: 8px;
    padding-right: 6px;
    display: inline-block;
}

.terms {
    font-size: 12px;
    text-align: center;
    margin-top: 10px;
    padding-top: 20px;
    line-height: 1.6;
}

.footer {
    border-top: 2px solid #000;
    font-size: 10px;
    text-align: center;
    margin-top: 50px;
    padding-top: 8px;
    line-height: 1.6;
}
